"""Self-contained observer dashboard for Zoe's local browser API."""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Zoe — Agent Browser</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#e8edf6;background:#0b1018}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 80% 0,#1a3045,transparent 40%),#0b1018}button,input,textarea,select{font:inherit}button{cursor:pointer;background:#192637;border:1px solid #31445a;color:#e8edf6;border-radius:8px;padding:9px 12px}button:hover{background:#243a50}button:disabled{opacity:.5;cursor:wait}.primary{background:#b9f27c;color:#11190b;border-color:#b9f27c;font-weight:700}input,textarea,select{width:100%;background:#0b121b;color:#e8edf6;border:1px solid #2a394b;border-radius:8px;padding:10px;min-width:0}label,.muted,.hint{font-size:12px;color:#91a4ba}.field{display:grid;gap:6px}.row{display:flex;gap:8px;align-items:center}.row>*{min-width:0}.grow{flex:1}.header{height:68px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #243041;position:sticky;top:0;background:#0b1018eF;backdrop-filter:blur(10px);z-index:2}.brand{display:flex;gap:11px;align-items:center}.logo{width:35px;height:35px;border-radius:11px;background:linear-gradient(140deg,#d7ff9d,#7eddb0);color:#11190b;display:grid;place-items:center;font-weight:900;font-size:20px}.brand h1{margin:0;font-size:17px}.brand p{margin:3px 0 0;font-size:10px;letter-spacing:1.5px;color:#8fa4bb}.badge{border:1px solid #36552d;color:#b9f27c;background:#142215;border-radius:99px;padding:7px 10px;font-size:11px}.layout{max-width:1550px;margin:auto;padding:20px;display:grid;grid-template-columns:285px minmax(0,1fr);gap:16px}.stack,.main{display:grid;gap:16px;align-content:start;min-width:0}.panel{background:#111923;border:1px solid #243041;border-radius:13px;overflow:hidden;min-width:0}.ph{padding:14px 15px;border-bottom:1px solid #243041;display:flex;align-items:center;justify-content:space-between;gap:8px}.ph h2{font-size:13px;margin:0}.pb{padding:14px;display:grid;gap:11px}.two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.address{padding:12px;display:flex;gap:8px;border-bottom:1px solid #243041}.address input{font-size:13px}.status{padding:8px 13px;border-bottom:1px solid #243041;display:flex;justify-content:space-between;gap:10px;color:#91a4ba;font-size:11px}.viewport{min-height:250px;padding:14px;background:#0c131d;display:grid;place-items:center}.empty{text-align:center;max-width:400px;color:#90a3ba}.empty h3{color:#e8edf6;font-size:15px}.empty p{font-size:12px;line-height:1.65}.preview{display:none;max-width:100%;max-height:450px;object-fit:contain;border-radius:8px;background:white}.below{display:grid;grid-template-columns:1fr 1fr;gap:16px}.content{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;background:#0b121b;border:1px solid #243041;border-radius:8px;padding:11px;font:12px/1.6 ui-monospace,monospace}.elements,.log{display:grid;gap:7px;max-height:240px;overflow:auto}.element{display:flex;gap:8px;align-items:flex-start;justify-content:space-between;background:#0b121b;border:1px solid #243041;border-radius:8px;padding:8px;font-size:12px}.element button{font-size:10px;padding:6px}.meta{font-size:10px;color:#8195ac;margin-top:4px}.task{min-height:155px;resize:vertical;font:12px/1.6 ui-monospace,monospace}.event{font-size:11px;line-height:1.5;background:#0b121b;border-left:2px solid #82b6f5;padding:8px 9px;overflow-wrap:anywhere}.event.error{border-color:#f58b86}.footer{max-width:1550px;margin:auto;padding:0 22px 20px;color:#6f8399;font-size:11px}.hidden{display:none!important}@media(max-width:950px){.layout{grid-template-columns:1fr;padding:12px}.stack{grid-template-columns:1fr 1fr}.below{grid-template-columns:1fr}}@media(max-width:600px){.stack{grid-template-columns:1fr}.header{padding:0 12px}.layout{padding:10px}.address{flex-wrap:wrap}.address input{flex-basis:100%}.badge{font-size:9px}.two{grid-template-columns:1fr}}
</style></head><body>
<header class="header"><div class="brand"><div class="logo">Z</div><div><h1>Zoe</h1><p>AI AGENT BROWSER</p></div></div><div class="badge">● LOCAL CONTROL · EXPERIMENTAL</div></header>
<div class="layout"><aside class="stack">
<section class="panel"><div class="ph"><h2>Browser session</h2><span class="muted" id="session-count">0 active</span></div><div class="pb"><div class="field"><label>ACTIVE SESSION</label><select id="sessions"><option value="">No session selected</option></select></div><div class="row"><button class="primary grow" id="create">＋ New session</button><button id="close">Close</button></div><div class="content" id="session-id">Create a session to begin.</div><p class="hint">Sessions isolate page state and cookies. More sessions use more memory.</p></div></section>
<section class="panel"><div class="ph"><h2>Direct actions</h2></div><div class="pb"><div class="field"><label>CSS SELECTOR</label><input id="selector" placeholder="button[type=submit]"></div><div class="field"><label>TEXT TO FILL</label><input id="fill-text" placeholder="Value for a field"></div><div class="row"><button class="grow" id="css-click">Click selector</button><button class="grow" id="css-fill">Fill selector</button></div><div class="two"><div class="field"><label>OPERATION</label><select id="op"><option>click</option><option>fill</option></select></div><div class="field"><label>LOCATE BY</label><select id="strategy"><option value="role">Role</option><option value="label">Label</option><option value="placeholder">Placeholder</option><option value="text">Text</option><option value="test_id">Test ID</option></select></div></div><div class="field"><label>LOCATOR VALUE</label><input id="locator" placeholder="Search or Submit"></div><div class="field" id="role-wrap"><label>ACCESSIBLE ROLE</label><input id="role" placeholder="button, link, textbox…"></div><div class="field hidden" id="semantic-fill-wrap"><label>TEXT TO FILL</label><input id="semantic-fill" placeholder="Text to enter"></div><button id="semantic">Run semantic action</button></div></section>
<section class="panel"><div class="ph"><h2>Activity log</h2><button id="clear-log">Clear</button></div><div class="pb"><div class="log" id="log"><span class="muted">Actions and outcomes appear here.</span></div></div></section>
</aside><main class="main">
<section class="panel"><div class="address"><input id="url" aria-label="Website URL" placeholder="https://example.com"><button class="primary" id="navigate">Navigate ↗</button><button id="inspect">Inspect</button><button id="screenshot">Screenshot</button></div><div class="status"><span id="title">No page loaded</span><span id="page-url">Awaiting navigation</span></div><div class="viewport"><div id="empty" class="empty"><div style="font-size:34px">⌘</div><h3>Your agent's window into the web</h3><p>Create a session, navigate to a public website, inspect structured content, and view screenshots. Zoe displays the browser rather than embedding the target website in this dashboard.</p></div><img id="preview" class="preview" alt="Screenshot of the browser page"></div></section>
<div class="below"><section class="panel"><div class="ph"><h2>Page observation</h2><span class="muted" id="char-count">0 characters</span></div><div class="pb"><div class="content" id="page-text">Navigate to a page and select Inspect.</div></div></section><section class="panel"><div class="ph"><h2>Interactive elements</h2><span class="muted" id="element-count">0 elements</span></div><div class="pb"><div class="elements" id="elements"><span class="muted">Elements appear after inspection.</span></div></div></section></div>
<section class="panel"><div class="ph"><h2>Run a bounded task</h2><span class="muted">20 steps · 60 seconds maximum</span></div><div class="pb"><p class="hint">Explicit steps only; this is not yet an autonomous planner. Include verification steps to check outcomes.</p><textarea id="task" class="task" spellcheck="false">{
  "timeout_seconds": 30,
  "steps": [
    {"action": "navigate", "url": "https://example.com"},
    {"action": "inspect"},
    {"action": "verify_text", "expected": "Example Domain"}
  ]
}</textarea><div class="row"><button class="primary" id="run-task">Run task</button><button id="load-example">Load example</button><span class="muted" id="task-status">Ready</span></div><div class="log" id="task-results"></div></div></section>
</main></div><div class="footer">Experimental local browser-control interface. Keep the API bound to 127.0.0.1; it has no authentication and must not be exposed to a public network.</div>
<script>
(()=>{const $=id=>document.getElementById(id);let sid="";const logroot=$("log"),example={timeout_seconds:30,steps:[{action:"navigate",url:"https://example.com"},{action:"inspect"},{action:"verify_text",expected:"Example Domain"}]};const time=()=>new Date().toLocaleTimeString();
function log(msg,error=false){if(logroot.querySelector(".muted"))logroot.replaceChildren();const e=document.createElement("div");e.className="event"+(error?" error":"");const t=document.createElement("span");t.style.color="#71869f";t.textContent=time()+" · ";const m=document.createElement("span");m.textContent=msg;e.append(t,m);logroot.prepend(e);while(logroot.children.length>50)logroot.lastElementChild.remove()}
async function api(path,options={}){const h=new Headers(options.headers||{});if(sid)h.set("X-Zoe-Session-ID",sid);if(options.body)h.set("Content-Type","application/json");const r=await fetch(path,{...options,headers:h});const type=r.headers.get("content-type")||"";const data=type.includes("application/json")?await r.json():await r.text();if(!r.ok)throw new Error(typeof data==="object"?(data.detail||JSON.stringify(data)):data);return data}
function busy(b,on,label){b.disabled=on;if(on){b.dataset.old=b.textContent;b.textContent=label||"Working…"}else if(b.dataset.old){b.textContent=b.dataset.old;delete b.dataset.old}}
async function act(name,fn,button){if(button)busy(button,true);try{const r=await fn();log(name+" — success");return r}catch(e){log(name+" — "+e.message,true);$("task-status").textContent=e.message;return null}finally{if(button)busy(button,false)}}
function needSession(){if(!sid)throw Error("Create or select a browser session first.")}
async function refreshSessions(preferred=""){const d=await api("/v1/sessions");const select=$("sessions");select.replaceChildren();const first=document.createElement("option");first.value="";first.textContent="No session selected";select.append(first);for(const s of d.sessions){const o=document.createElement("option");o.value=s.session_id;o.textContent=s.session_id.slice(0,10)+(s.browser_started?" · running":" · idle");select.append(o)}$("session-count").textContent=d.active_sessions+" active";if(preferred)sid=preferred;if(sid&&!d.sessions.some(s=>s.session_id===sid))sid="";select.value=sid;$("session-id").textContent=sid||"Create a session to begin."}
async function inspectPage(){needSession();const d=await api("/v1/browser/inspect");$("title").textContent=d.title||"Untitled page";$("page-url").textContent=d.url||"";$("url").value=d.url||$("url").value;$("page-text").textContent=d.text||"";$("char-count").textContent=(d.text||"").length+" characters"+(d.text_truncated?" · truncated":"");const root=$("elements");root.replaceChildren();const els=d.interactive_elements||[];$("element-count").textContent=els.length+" elements";if(!els.length)root.textContent="No visible interactive elements detected.";for(const el of els){const row=document.createElement("div");row.className="element";const wrap=document.createElement("div");const title=document.createElement("div");title.textContent=(el.text||el.aria_label||el.placeholder||"(unnamed "+el.tag+")").slice(0,160);const meta=document.createElement("div");meta.className="meta";meta.textContent=el.tag+(el.role?" · "+el.role:"")+(el.type?" · "+el.type:"")+(el.disabled?" · disabled":"");wrap.append(title,meta);const use=document.createElement("button");use.textContent="Use selector";use.disabled=el.disabled;use.onclick=()=>{const selector=el.id?"#"+CSS.escape(el.id):el.name?el.tag+'[name="'+String(el.name).replace(/"/g,'\\"')+'"]':el.tag;$("selector").value=selector;log("Prepared selector "+selector)};row.append(wrap,use);root.append(row)}return d}
async function screenshot(){needSession();const d=await api("/v1/browser/screenshot");$("preview").src="data:"+d.mime_type+";base64,"+d.data;$("preview").style.display="block";$("empty").classList.add("hidden")}
$("create").onclick=()=>act("Create session",async()=>{const s=await api("/v1/sessions",{method:"POST"});await refreshSessions(s.session_id);log("Session created "+sid)},$("create"));
$("sessions").onchange=()=>{sid=$("sessions").value;$("session-id").textContent=sid||"Create a session to begin.";log(sid?"Selected session "+sid:"Session deselected")};
$("close").onclick=()=>act("Close session",async()=>{needSession();const old=sid;await api("/v1/sessions/"+encodeURIComponent(old),{method:"DELETE"});sid="";await refreshSessions();$("preview").style.display="none";$("empty").classList.remove("hidden");log("Closed "+old)},$("close"));
$("navigate").onclick=()=>act("Navigate",async()=>{needSession();const d=await api("/v1/browser/navigate",{method:"POST",body:JSON.stringify({url:$("url").value.trim()})});$("title").textContent=d.title||"Untitled page";$("page-url").textContent=d.url||"";if(!d.success)log("HTTP response was not successful: "+d.http_status,true);await inspectPage();await screenshot()},$("navigate"));
$("url").onkeydown=e=>{if(e.key==="Enter")$("navigate").click()};
$("inspect").onclick=()=>act("Inspect page",inspectPage,$("inspect"));$("screenshot").onclick=()=>act("Screenshot",screenshot,$("screenshot"));
$("css-click").onclick=()=>act("CSS click",async()=>{needSession();await api("/v1/browser/click",{method:"POST",body:JSON.stringify({selector:$("selector").value.trim()})});await inspectPage();await screenshot()},$("css-click"));
$("css-fill").onclick=()=>act("CSS fill",async()=>{needSession();await api("/v1/browser/fill",{method:"POST",body:JSON.stringify({selector:$("selector").value.trim(),text:$("fill-text").value})});await inspectPage();await screenshot()},$("css-fill"));
function syncSemantic(){const filling=$("op").value==="fill";$("semantic-fill-wrap").classList.toggle("hidden",!filling);for(const option of $("strategy").options)option.disabled=filling&&!["label","placeholder","test_id"].includes(option.value);if(filling&&$("strategy").selectedOptions[0].disabled)$("strategy").value="label";$("role-wrap").classList.toggle("hidden",filling||$("strategy").value!=="role")} $("op").onchange=syncSemantic;$("strategy").onchange=syncSemantic;syncSemantic();
$("semantic").onclick=()=>act("Semantic action",async()=>{needSession();const op=$("op").value,strategy=$("strategy").value,body={action:op,strategy,value:$("locator").value.trim(),exact:true};if(strategy==="role")body.role=$("role").value.trim();if(op==="fill")body.text=$("semantic-fill").value;await api("/v1/browser/action",{method:"POST",body:JSON.stringify(body)});await inspectPage();await screenshot()},$("semantic"));
$("load-example").onclick=()=>{$("task").value=JSON.stringify(example,null,2);$("task-status").textContent="Example loaded"};
$("run-task").onclick=()=>act("Run task",async()=>{needSession();let body;try{body=JSON.parse($("task").value)}catch(e){throw Error("Invalid JSON: "+e.message)}busy($("run-task"),true,"Running…");$("task-status").textContent="Executing…";$("task-results").replaceChildren();try{const d=await api("/v1/tasks/run",{method:"POST",body:JSON.stringify(body)});$("task-status").textContent=d.success?"Completed":"Failed at step "+d.stopped_at_step;for(const s of d.steps){const e=document.createElement("div");e.className="event"+(s.success?"":" error");e.textContent="#"+s.index+" "+s.action+" · "+s.duration_ms+" ms · "+(s.success?"success":s.error);$("task-results").append(e)}log("Task "+(d.success?"completed":"failed")+" ("+d.completed_steps+"/"+d.total_steps+" successful steps)");await inspectPage();await screenshot()}finally{busy($("run-task"),false)}},$("run-task"));
$("clear-log").onclick=()=>{logroot.innerHTML='<span class="muted">Actions and outcomes appear here.</span>'};refreshSessions().catch(e=>log("API unavailable: "+e.message,true));
})();
</script></body></html>
"""
